	public static function get_localize_able_svg_icon() {
		$svgs = self::get_svgs();
		return [
			'upvote-up-outline' => $svgs['upvote-up-outline'],
			'upvote-up-filled' => $svgs['upvote-up-filled'],
			'bookmark-filled' => $svgs['bookmark-filled'],
			'bookmark-outline' => $svgs['bookmark-outline'],
		];
	}

	/**
	 * Sanitize an arbitrary SVG string against an element/attribute allowlist so
	 * stored SVG markup (e.g. admin-configured reaction icons) can be echoed safely.
	 *
	 * @param string $svg
	 * @return string
	 */
	public static function kses_svg( $svg ) {
		$common = [
			'class' => true, 'fill' => true, 'stroke' => true, 'stroke-width' => true,
			'stroke-linecap' => true, 'stroke-linejoin' => true, 'stroke-dasharray' => true,
			'transform' => true, 'opacity' => true, 'style' => true, 'id' => true,
		];
		$allowed = [
			'svg'      => array_merge( $common, [ 'xmlns' => true, 'viewbox' => true, 'width' => true, 'height' => true, 'aria-hidden' => true, 'role' => true, 'focusable' => true ] ),
			'g'        => $common,
			'path'     => array_merge( $common, [ 'd' => true, 'fill-rule' => true, 'clip-rule' => true ] ),
			'circle'   => array_merge( $common, [ 'cx' => true, 'cy' => true, 'r' => true ] ),
			'ellipse'  => array_merge( $common, [ 'cx' => true, 'cy' => true, 'rx' => true, 'ry' => true ] ),
			'rect'     => array_merge( $common, [ 'x' => true, 'y' => true, 'width' => true, 'height' => true, 'rx' => true, 'ry' => true ] ),
			'line'     => array_merge( $common, [ 'x1' => true, 'y1' => true, 'x2' => true, 'y2' => true ] ),
			'polyline' => array_merge( $common, [ 'points' => true ] ),
			'polygon'  => array_merge( $common, [ 'points' => true ] ),
			'defs'     => $common,
			'use'      => array_merge( $common, [ 'href' => true, 'xlink:href' => true ] ),
			'title'    => [],
		];

		return wp_kses( (string) $svg, $allowed );
	}

	public static function get_svg_icon( string $name, ?string $fill = null, ?string $d = null, ?string $view_box = null, ?string $class = null ): ?string {
		$icons = self::get_svgs();

		if ( ! isset( $icons[ $name ] ) && null !== $d ) {
			return null;
		}

		$icon = $icons[ $name ] ?? [];

		$pathD   = $d ?? ( $icon['d'] ?? null );
		$viewBox = $icon['viewBox'] ?? $view_box ?? '0 0 20 20';
		$fill    = $fill ?? $icon['fill'] ?? '#f59e0b';
		$stroke  = 'null';

		$classList = trim(
			trim( (string) ( $icon['class'] ?? '' ) ) . ' ' . trim( (string) ( $class ?? '' ) )
		);
		$classAttr = $classList ? ' class="' . esc_attr( $classList ) . '"' : '';

		if ( ! $pathD ) {
			return null;
		}

		return sprintf(
			'<svg width="20" height="20"%s viewBox="%s" xmlns="http://www.w3.org/2000/svg"><path d="%s" fill="%s" stroke="%s" stroke-linejoin="null"/></svg>',
			$classAttr,
			esc_attr( $viewBox ),
			esc_attr( $pathD ),
			esc_attr( $fill ),
			esc_attr( $stroke )
		);
	}
}
